#define iterations 11
#define formuparam 0.53

#define volsteps 20
#define stepsize 0.1

#define zoom   0.800
#define tile   0.850
#define speed  0.000 

#define brightness 0.0015
#define darkmatter 0.300
#define distfading 0.730
#define saturation 0.850


#define BlockSize vec2(20,20)
#define seed 2564.12354

float hash12(vec2 p)
{
	p=p+seed;
	vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}


float sdSegment( in vec2 p, in vec2 a, in vec2 b ) {
	 vec2 pa = p-a, ba = b-a; 
	 float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 ); 
	 return length( pa - ba*h ); 
}


#define PI 3.141592
#define tt iTime
#define S(a, b, x) smoothstep(a, b, x)
#define rot(x) mat2(cos(x), -sin(x), sin(x), cos(x))

vec3 pal(float x) {
    return .5+.5*cos(2.*PI*x+vec3(0, 8, 10));

}

float circle(vec2 p, float r) {
    return length(p) - r;
}

float box(vec2 p, vec2 s) {
    p = abs(p);
    return max(p.x - s.x, p.y - s.y);
}

vec2 toPolar(vec2 p) {
    float a = atan(p.y, p.x);
    float r = length(p);

    return vec2(r, a);
}

vec2 fromPolar(vec2 p) {

    return p.x*vec2(cos(p.y), sin(p.y));
}
float rug(vec2 p) {

      vec3 r = normalize(vec3(p.xy, 1.0 - dot(p.xy, p.xy) *10.3));
    p = fract(p*2.)-.5;


  //  fe
      p = abs(p)-.1;
    for(float i=.0; i< 5.; i++ ) {
       p.x = abs(p.x) - .2;
       p.x += sin(p.y*.2+i)*.3;
       p.xy *= rot(PI/9.+i); 
    }
        p = toPolar(p);
    float N = 2.;
    p.y = fract(p.y*N/PI*2.)-.5; 
    p.x = abs(p.x)+ .3;
    p = fromPolar(p);



    vec2 bp = p;

    float d = 1e0;

    p.x -= .2;
    d = circle(p+r.xy, .4);
    d = abs(d) - .02;

    p = bp;

    p.x += .2;
    float d2 = circle(p, .4);
    d2 = abs(d2) - .02;

    d = min(d, d2);

    p = bp;
    p = abs(p);
    p.x -= .49;
    p.xy *= rot(.25*PI);

    d2 = box(p, vec2(.19));
    d2 = abs(d2) - .02;

    d = min(d, d2);

    d = abs(d) -.003;

    return d;
}

float geometry(vec2 fc){

	vec2 blockCoord = floor(fc / BlockSize);
	vec2 blockPos = blockCoord * BlockSize;
   blockCoord/=1.-blockCoord.y*2.+cos(iTime*0.02);
    float d2 = rug(fract(fc*2.));
	float hv = hash12(blockCoord.xx);
	float hh = hash12(blockCoord.yy);

	vec2 pt1Mult = hv>hh ? vec2(0.,.5) : vec2(.5,0);
	vec2 pt2Mult = hv>hh ? vec2(1.,.5) : vec2(.5,1);

	float d = sdSegment(fc,blockPos+BlockSize*pt1Mult,blockPos+BlockSize*pt2Mult);

	return d-6.;  
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	//get coords and direction
	vec2 uv=fragCoord.xy/iResolution.xy-.5;
	uv.y*=iResolution.y/iResolution.x;
	vec3 dir=vec3(uv*zoom,1.);
	float time=iTime*speed+.25;

float a2=iTime*0.05;
	mat2 rot2=mat2(cos(a2),sin(a2),-sin(a2),cos(a2));


	vec3 from=vec3(1.,.5,0.5);


	//volumetric rendering
	float s=0.1,fade=1.;
	vec3 v=vec3(0.);
	for (int r=0; r<volsteps; r++) {
		vec3 p=from+s*dir*.5;
		p = abs(vec3(tile)-mod(p,vec3(tile*2.))); // tiling fold
		float pa,a=pa=0.;
		for (int i=0; i<iterations; i++) { 
			p=abs(p)/dot(p,p)-formuparam;
            p.xy*=rot2;// the magic formula
			a+=abs(length(p)-pa); // absolute sum of average change
			pa=length(p);
		}
		float dm=max(0.,darkmatter-a*a*.001); //dark matter
		a*=a*a; // add contrast
		if (r>6) fade*=1.2-dm; // dark matter, don't render near
		//v+=vec3(dm,dm*.5,0.);
		v+=fade;
		v+=vec3(s,s*s,s*s*s*s)*a*brightness*fade; // coloring based on distance
		fade*=distfading; // distance fading
		s+=stepsize;
	}
	v=mix(vec3(length(v)),v,saturation); //color adjust

       vec2 uvb = uv;
    uv *= 1.3;

    float d = rug(fract(uv*2.));
    float s1 = (1.-S(0., .02, d));

    vec3 col =  pal(-d*20. + (abs(uv.x)+abs(uv.y)))*s1;

    float d2 = (rug(uv));
    float s2 = (1.-S(0., .01, d2));
    col = mix(pal(-d2*20.-.8+abs(uv.x)+abs(uv.y))*s2, col, s1);


    col = mix(mix(vec3(0.718,0.145,0.043), vec3(0.957,0.718,0.204)*.2, abs(uv.x)), col, dot(col, vec3(1)));

    col *= S(0.0, 0.01, d2*2.);


    float rimd = abs(box(uvb, vec2(.62, .4)*.8))- 0.03; 
    float rim = S(0., .005, rimd);
    col *= rim;

    vec3 rimCol = pal(-rimd*10.-.8+abs(uv.x)+abs(uv.y));
    float circles = abs(circle(fract(uv*18.)-.5, .2)) -.1;

    col += (1.-rim)*(1.-S(0., .1, abs(circles)-.02)*S(0., 0.01, abs(rimd)))*rimCol;



    col *= 1.-S(0., .02, box(uvb, vec2(.6, .4)));
    float edge = (1.-S(0., .01, abs(box(uvb, vec2(.6, .4))-.01)));
    col = mix(col, rimCol, edge);
    col *= 1.-.9*texture(iChannel0, uvb*3.).r; 
	float lines = geometry(fragCoord.xy+vec2(iTime*0.)*vec2(90,30));

	fragColor = vec4(v*.03,1.);	
    fragColor *= vec4(vec3(lines*col*2.), 1.0);

}
